import java.util.*;
import java.nio.file.*;

class Store {
    // 파일의 각 줄은 번호:내용이에요. 내용 안의 콜론은 남겨요.
    static Map<Integer,String> load(Path path) throws Exception {
        Map<Integer,String> loaded = new LinkedHashMap<>();
        for (String line : Files.readAllLines(path)) {
            String[] parts = line.split(":",2);
            loaded.put(Integer.parseInt(parts[0]),parts[1]);
        }
        return loaded;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Path path = Path.of(new Scanner(System.in).nextLine());
        System.out.println(Store.load(path));
    }
}

